-- Supplied vehicle pose atlases; preserve all previously shipped frames and selections.
ALTER TABLE profile_frames ADD COLUMN vehicle_atlas_url TEXT, ADD COLUMN vehicle_preview_url TEXT;
ALTER TABLE profile_frames DROP CONSTRAINT profile_frames_media_check;
ALTER TABLE profile_frames ADD CONSTRAINT profile_frames_media_check CHECK(family IN ('dragon','rose','blade','crystal','celestial','cat','racing') AND color ~ '^#[0-9a-fA-F]{6}$' AND accent ~ '^#[0-9a-fA-F]{6}$' AND duration_ms>0 AND fps>=0 AND price_cents>=0 AND (NOT animated OR fps>0));
ALTER TABLE profile_frames ADD CONSTRAINT profile_frames_vehicle_check CHECK(family <> 'racing' OR (vehicle_atlas_url IS NOT NULL AND vehicle_preview_url IS NOT NULL));
INSERT INTO profile_frames(id,slug,name,description,family,variant,color,accent,crown_url,crown_preview_url,corner_url,rail_url,footer_url,vehicle_atlas_url,vehicle_preview_url,animated,fps,duration_ms,rarity,price_cents,is_available) VALUES
('profile-frame-racing-formula','profile-frame-racing-formula','Apex Circuit • Formula 1','Два наших 3D-болида проходят повороты по периметру профиля. Ледяные следы, карбоновая оправа и финишные флаги оформляют трассу.','racing','racing-formula','#299dff','#d9f5ff','/Profile-decorations/Profile-frames/profile-frame-racing-formula.crown.svg?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-formula.crown.preview.webp?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-formula.corner.svg?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-formula.rail.svg?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-formula.footer.svg?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-formula.vehicle-atlas.webp?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-formula.vehicle.preview.webp?v=1',TRUE,60,8000,'epic',199,FALSE),
('profile-frame-racing-kart','profile-frame-racing-kart','Neon Paddock • Kart','Два наших 3D-карта едут по неоновой трассе вокруг профиля. Фиолетовое свечение, лаймовые акценты и клетчатые бордюры поддерживают цвета модели.','racing','racing-kart','#9d67f5','#d9f86a','/Profile-decorations/Profile-frames/profile-frame-racing-kart.crown.svg?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-kart.crown.preview.webp?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-kart.corner.svg?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-kart.rail.svg?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-kart.footer.svg?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-kart.vehicle-atlas.webp?v=1','/Profile-decorations/Profile-frames/profile-frame-racing-kart.vehicle.preview.webp?v=1',TRUE,60,8000,'epic',199,FALSE);
